import{_ as n,c as i,a2 as r,o as a}from"./chunks/framework.rHWNTPhC.js";const m=JSON.parse('{"title":"Ergebnismeldung-Service","description":"","frontmatter":{},"headers":[],"relativePath":"services/ergebnismeldung-service/index.md","filePath":"services/ergebnismeldung-service/index.md"}'),t={name:"services/ergebnismeldung-service/index.md"};function l(s,e,h,d,u,b){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="ergebnismeldung-service" tabindex="-1">Ergebnismeldung-Service <a class="header-anchor" href="#ergebnismeldung-service" aria-label="Permalink to &quot;Ergebnismeldung-Service&quot;">​</a></h1><p>Service der Informationen und Operationen für die Ergebnisse einer Wahl bereitstellt. Dabei geht es um die Ergebnisse die durch den Nutzer anhand von Masken erfasst werden.</p><h2 id="abhangigkeiten" tabindex="-1">Abhängigkeiten <a class="header-anchor" href="#abhangigkeiten" aria-label="Permalink to &quot;Abhängigkeiten&quot;">​</a></h2><p>Folgende Services werden benötigt:</p><ul><li>Basisdaten-Service</li><li>Briefwahl-Service</li><li>EAI-Service</li><li>Infomanagement-Service</li><li>Monitoring-Service</li><li>Wahlvorbereitung-Service</li></ul><h2 id="daten-und-funktionen" tabindex="-1">Daten und Funktionen <a class="header-anchor" href="#daten-und-funktionen" aria-label="Permalink to &quot;Daten und Funktionen&quot;">​</a></h2><ul><li>Verwalten und Übermitteln von Ergebnismeldungen</li><li>Verwalten von A- und B-Werten</li></ul><h3 id="abrufen-von-a-werten-wahlberechtigte" tabindex="-1">Abrufen von A-Werten (Wahlberechtigte) <a class="header-anchor" href="#abrufen-von-a-werten-wahlberechtigte" aria-label="Permalink to &quot;Abrufen von A-Werten (Wahlberechtigte)&quot;">​</a></h3><p>Die Methode <code>getAWerte()</code> liefert die A-Werte für eine bestimmte Wahlbezirk-ID. Die A-Werte repräsentieren die Anzahl der Wahl- bzw. Stimmberechtigten in einem Wahlbezirk. Sie teilen sich auf in die Anzahl an Wahlberechtigten, die keinen Wahlschein erhalten haben (A1) und in die Anzahl an Wahlberechtigten, die einen Wahlschein erhalten haben und deshalb einen W-Vermerk im Wählerverzeichnis besitzen (A2).</p><ul><li>Wenn über die EAI im externen Wahlsystem Daten gefunden werden, dann werden diese im lokalen Repository gespeichert und zurück gegeben.</li><li>Sofern über die EAI im externen Wahlsystem keine Daten gefunden werden können, wird versucht auf &#39;alte&#39; A-Werte im lokalen Repository zuzugreifen.</li><li>Falls weder im externen Wahlsystem noch im lokalen Repository A-Werte gefunden werden liefert der Service einen Fehler.</li></ul><h3 id="initialisieren-von-a-werten-wahlberechtigte" tabindex="-1">Initialisieren von A-Werten (Wahlberechtigte) <a class="header-anchor" href="#initialisieren-von-a-werten-wahlberechtigte" aria-label="Permalink to &quot;Initialisieren von A-Werten (Wahlberechtigte)&quot;">​</a></h3><p>Die Methode initialisiereAWerte() initialisiert die Wahlberechtigten (A-Werte) für eine Liste an Wahlbezirk-IDs.</p><ul><li>Für jede Wahlbezirk-ID in der Liste wird über die EAI im externen Wahlsystem nach A-Werten gesucht. Bei Erfolg werden diese im lokalen Repository gespeichert.</li><li>Bei Nichterfolg wird geprüft, ob im lokalen Repository wenigstens &#39;alte&#39; A-Werte existieren.</li><li>Falls weder im externen Wahlsystem noch im lokalen Repository A-Werte gefunden werden liefert der Service einen Fehler.</li></ul><h3 id="update-des-status-der-ergebnisermittlung" tabindex="-1">Update des Status der Ergebnisermittlung <a class="header-anchor" href="#update-des-status-der-ergebnisermittlung" aria-label="Permalink to &quot;Update des Status der Ergebnisermittlung&quot;">​</a></h3><p>Bei der Auszählung (Ergebnisermittlung) wird zuerst eine Schnellmeldung vorbereitet. Den Abschluss der Auszählung bildet die Niederschrift. Die Schnellmeldung und die Niederschrift können gedruckt und übermittelt werden.</p><p>Welche Aktionen für die jeweiligen Dokumente bereits in einem Wahllokal vollzogen wurden, wird über den Status gepflegt.</p><p>Über Änderungen an dem Status wird auch der <a href="/Wahllokalsystem/services/monitoring-service/">Monitoring-Service</a> informiert.</p><h3 id="lesen-und-schreiben-von-stimmabgabevermerken" tabindex="-1">Lesen und Schreiben von Stimmabgabevermerken <a class="header-anchor" href="#lesen-und-schreiben-von-stimmabgabevermerken" aria-label="Permalink to &quot;Lesen und Schreiben von Stimmabgabevermerken&quot;">​</a></h3><h4 id="erfassung-der-stimmabgaben-mit-wahlschein" tabindex="-1">Erfassung der Stimmabgaben mit Wahlschein <a class="header-anchor" href="#erfassung-der-stimmabgaben-mit-wahlschein" aria-label="Permalink to &quot;Erfassung der Stimmabgaben mit Wahlschein&quot;">​</a></h4><p>Im Wählerverzeichnis wird bei einer Wahl durch den Schriftführer über den sogenannten &quot;Stimmabgabevermerk&quot; vermerkt, wenn ein Wahlberechtigter mit Wahlschein seinen Stimmzettel in die Urne im Wahllokal gelegt hat. Über das Schreiben und Lesen der Wahlscheine kann die aktuelle Anzahl an Stimmabgabevermerken an WLS übermittelt bzw. ausgelesen werden.</p><h3 id="erfassung-der-anzahl-an-stimmzettelumschlaegen" tabindex="-1">Erfassung der Anzahl an Stimmzettelumschlaegen <a class="header-anchor" href="#erfassung-der-anzahl-an-stimmzettelumschlaegen" aria-label="Permalink to &quot;Erfassung der Anzahl an Stimmzettelumschlaegen&quot;">​</a></h3><p>Bei der Briefwahl zählt der Wahlvorstand die Stimmzettelumschlaege. Über das Schreiben und Lesen der Stimmzettelumschlaege kann die aktuelle Anzahl eines Wahlbezirkes für eine Wahl an WLS übermittelt bzw. ausgelesen werden.</p><h3 id="lesen-und-schreiben-von-ausdrucken" tabindex="-1">Lesen und Schreiben von Ausdrucken <a class="header-anchor" href="#lesen-und-schreiben-von-ausdrucken" aria-label="Permalink to &quot;Lesen und Schreiben von Ausdrucken&quot;">​</a></h3><p>Hier können Niederschrift(V1) und Schnellmeldung(V3) gespeichert und gelesen werden.</p><h4 id="speichern-eines-ausdrucks-mit-bestimmter-meldungsart-fur-einen-wahlbezirk-einer-wahl" tabindex="-1">Speichern eines Ausdrucks mit bestimmter Meldungsart für einen Wahlbezirk einer Wahl <a class="header-anchor" href="#speichern-eines-ausdrucks-mit-bestimmter-meldungsart-fur-einen-wahlbezirk-einer-wahl" aria-label="Permalink to &quot;Speichern eines Ausdrucks mit bestimmter Meldungsart für einen Wahlbezirk einer Wahl&quot;">​</a></h4><p>Speichert einen Ausdruck der entsprechenden Meldungsart für einen Wahlbezirk einer Wahl. Es wird automatisch ein aktuelles Erstellungsdatum mit erzeugt und gespeichert.</p><h3 id="lesen-eines-ausdrucks-mit-bestimmter-meldungsart-fur-einen-wahlbezirk-einer-wahl" tabindex="-1">Lesen eines Ausdrucks mit bestimmter Meldungsart für einen Wahlbezirk einer Wahl <a class="header-anchor" href="#lesen-eines-ausdrucks-mit-bestimmter-meldungsart-fur-einen-wahlbezirk-einer-wahl" aria-label="Permalink to &quot;Lesen eines Ausdrucks mit bestimmter Meldungsart für einen Wahlbezirk einer Wahl&quot;">​</a></h3><p>Liest einen Ausdruck mit entsprechender Meldungsart für einen Wahlbezirk einer Wahl.</p><h3 id="lesen-aller-ausdrucke-fur-einen-wahlbezirk-einer-wahl" tabindex="-1">Lesen aller Ausdrucke für einen Wahlbezirk einer Wahl <a class="header-anchor" href="#lesen-aller-ausdrucke-fur-einen-wahlbezirk-einer-wahl" aria-label="Permalink to &quot;Lesen aller Ausdrucke für einen Wahlbezirk einer Wahl&quot;">​</a></h3><p>Liest alle Ausdrucke (V1 und V3) für einen Wahlbezirk einer Wahl.</p><h3 id="lesen-und-schreiben-von-ergebnissen" tabindex="-1">Lesen und Schreiben von Ergebnissen <a class="header-anchor" href="#lesen-und-schreiben-von-ergebnissen" aria-label="Permalink to &quot;Lesen und Schreiben von Ergebnissen&quot;">​</a></h3><p>Wahlergebnisse können gespeichert werden. Die Ergebnisse werden über ihren Wahlbezirk, ihre Wahl und den Stapel, auf dem sie liegen, ausgelesen. Es können auch die Ergebnisse von allen Stapeln einer Wahl in einem Wahlbezirk gelesen werden.</p><h3 id="lesen-und-schreiben-von-begrundungen" tabindex="-1">Lesen und Schreiben von Begründungen <a class="header-anchor" href="#lesen-und-schreiben-von-begrundungen" aria-label="Permalink to &quot;Lesen und Schreiben von Begründungen&quot;">​</a></h3><p>Zu Wahlergebnissen können Begründungen verfasst werden, in denen festgehalten wird, wieso ein Wahlergebnis trotz Abweichungen in der Anzahl der Stimmen gespeichert wird.</p>',34)]))}const o=n(t,[["render",l]]);export{m as __pageData,o as default};
